    }
    if (!EMAIL_PATTERN.matcher(email).matches()) {
        throw new InvalidEmailException(email);
    }
    String normalized = email.toLowerCase(Locale.ROOT);
    String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
